public class GatewayTargetFactory(string resourceName = null, Action<Humidifier.BedrockAgentCore.GatewayTarget> factoryAction = null) : ResourceFactory<Humidifier.BedrockAgentCore.GatewayTarget>(resourceName)
{

    internal List<InnerGatewayTargetCertificateConfigurationFactory> CertificateConfigurationsFactories { get; set; } = [];

    internal List<InnerGatewayTargetCredentialProviderConfigurationFactory> CredentialProviderConfigurationsFactories { get; set; } = [];

    internal InnerGatewayTargetTargetConfigurationFactory TargetConfigurationFactory { get; set; }

    internal InnerGatewayTargetMetadataConfigurationFactory MetadataConfigurationFactory { get; set; }

    internal InnerGatewayTargetPrivateEndpointFactory PrivateEndpointFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTarget Create()
    {
        var gatewayTargetResult = CreateGatewayTarget();
        factoryAction?.Invoke(gatewayTargetResult);

        return gatewayTargetResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTarget CreateGatewayTarget()
    {
        var gatewayTargetResult = new Humidifier.BedrockAgentCore.GatewayTarget
        {
            GivenName = InputResourceName,
        };

        return gatewayTargetResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTarget result)
    {
        base.CreateChildren(result);

        result.CertificateConfigurations = CertificateConfigurationsFactories.Any() ? CertificateConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.CredentialProviderConfigurations = CredentialProviderConfigurationsFactories.Any() ? CredentialProviderConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.TargetConfiguration ??= TargetConfigurationFactory?.Build();
        result.MetadataConfiguration ??= MetadataConfigurationFactory?.Build();
        result.PrivateEndpoint ??= PrivateEndpointFactory?.Build();
    }

} // End Of Class

